// Boundary check of the 1 MiB import limit, using the real app/backup.js.
const path = require('node:path');
const backup = require(path.resolve(process.argv[2], 'app/backup.js'));
const { MAX_IMPORT_BYTES, MESSAGES, toBackupText, tooBigToImport, importBackup } = backup;

const bytes = (s) => new TextEncoder().encode(s).length;

// A valid backup with a multi-byte (Vietnamese) title, so bytes != characters, padded with trailing
// whitespace (allowed by JSON.parse) to exactly `size` bytes.
function backupOfSize(size) {
  const base = toBackupText([{ id: 'a1', title: 'Mua rau cải, đậu phụ', done: false, createdAt: 1761700000000 }]);
  const text = base + ' '.repeat(size - bytes(base));
  if (bytes(text) !== size) throw new Error('padding wrong');
  return text;
}

function fakeStore() {
  return { readError: false, replaced: null, replace(t) { this.replaced = t; return 'saved'; }, save() { throw new Error('save called'); } };
}

(async () => {
  console.log('MAX_IMPORT_BYTES =', MAX_IMPORT_BYTES, MAX_IMPORT_BYTES === 1024 * 1024 ? '(= 1024*1024)' : '(NOT 1 MiB)');
  for (const size of [MAX_IMPORT_BYTES - 1, MAX_IMPORT_BYTES, MAX_IMPORT_BYTES + 1]) {
    const text = backupOfSize(size);
    const file = new Blob([text]);
    const store = fakeStore();
    const r = await importBackup({ store, current: [], file, ask: async () => true });
    const outcome = r.message === MESSAGES.fileTooBig ? 'fileTooBig' : r.message;
    console.log(
      `size=${size} chars=${text.length} blob.size=${file.size} tooBigToImport=${tooBigToImport(text)} ` +
      `importBackup -> "${outcome}" replaced=${store.replaced ? store.replaced.length : 'no'}`,
    );
  }
})();

